#include "types.h"
#include "qb_constants.h"

/* Full decode of the WANT (0x801B9FD0, 174 words, 696B), rodata constants:
 *   0x802ABFB8 = {0.0f, 0.0f} (zero pair, ps_merge00 partner)
 *   0x802AC280 = 0.5f, 0x802AC284 = 0.0f, 0x802AC288 = 1.0f
 * arg0(A): 0x0C -> B*, 0x78/0x80 = two vec2
 * B:        0x58/0x60 = two vec2
 * arg2(C):  0x18 -> QB param block
 *
 *   frame 0xD0; F29=jt  F30=jh  F31=spd (then spd2); pair slots at
 *   0x08=d2 0x10=d1 0x18/0x20=v2s/v1s 0x28/0x30=dead 0x38..0x47 = "seg1"
 *   0x48..0x57 = "seg2" (0x48 is the &arg passed to fn_801279A0) 0x58/0x5C =
 *   height/gravity 0x60=inv 0x68=inv2 0x70=spd 0x78=jh 0x80=inv3 0x88=inv4
 *
 * Algorithm:
 *   d1 = a->v80 - b->v60 ; d2 = a->v78 - b->v58
 *   jt = 2*sqrt(2*(-h)/g)          (QB_JUMPTIME)
 *   jh = sqrt(2*g*(-h))            (jump height)
 *   inv  = 1/sqrt(|d1|2 + |d2|2)
 *   spd  = inv * 0.5f * fn_8012570C(SLOP_DISTANCE,1) / jt   (QB_JUMPSPEED)
 *   if (dist > 0) d1 *= 1/sqrt(dist); d2 *= 1/sqrt(dist)
 *   v = {d2,d1} * spd  +  {0,1} * jh         (seg1 = {v2,v1}, seg2 = {v2,v1})
 *   inv3 = 1/sqrt(|v2|2 + |v1|2)
 *   if (|v|2 > 0) seg2 = {v2,v1} * 1/sqrt(|v|2)
 *   seg1 = seg2
 *   fn_801279A0(qb, QB_HEADING, &seg2.x); SetFloat(qb,QB_JUMPSPEED,inv3);
 *   SetFloat(qb,QB_JUMPTIME,jt); return 1
 * Both dot products go through the SAME `ps_merge00(.., {0,0})` + `ps_madd` +
 * `ps_sum0` + `ps_rsqrte` + `ps_res` chain (only lane 0 of the pair is used).
 */

typedef struct {
    char pad[0x58];
    __ps_t v58;
    __ps_t v60;
} B;

typedef struct {
    char pad[0x0C];
    B *b;
    char pad2[0x68];
    __ps_t v78;
    __ps_t v80;
} A;

typedef struct {
    char pad[0x18];
    void *p;
} C;

typedef struct Qb Qb;

extern __ps_t lbl_802ABFB8;
extern f32 lbl_802AC280;
extern f32 lbl_802AC284;
extern f32 lbl_802AC288;

extern s32 GetFloat(Qb *, s32, f32 *, s32);
extern f32 sqrtf(f32);
extern f32 fn_8012570C(s32, s32);
extern void fn_801279A0(void *, s32, void *);
extern void fn_8012772C(void *, s32, f32);

/* A frame pair with lane access: the game stores a whole psq pair and then
 * overwrites lane 1 with a separate scalar `stfs` (0x68/0x88 + 0x6c/0x8c), so
 * the union is load-bearing. */
typedef union {
    __ps_t ps;
    f32 f[2];
} P2;

/* seg1 (0x38..0x47) and seg2 (0x48..0x57): two independent 16-byte vec2 pairs
 * holding the same {v2, v1}; seg2 is the one passed to fn_801279A0. */
typedef struct {
    P2 x;
    P2 y;
} V4;

typedef struct {
    __ps_t d2;
    __ps_t d1;
    __ps_t v2s;
    __ps_t v1s;
    V4 g;
    V4 s1;
    V4 s2;
    f32 h;
    f32 grav;
} T;

s32 fn_801B9FD0(A *a, Qb *qb, C *c) {
    T t;
    /* recipes §6ez/§7q: 0x60..0x88 must be STANDALONE non-escaping locals, not
     * members of `t`. With members cc1 coalesces each reload into its consumer
     * and every `fmr`/`ps_mr` after the reload disappears (that was 5 of the 7
     * missing words here). ngccc then lays them out in declaration order at
     * 0x60/0x68/0x70/0x78/0x80/0x88, i.e. splitting `t` at h/grav is
     * offset-neutral. */
    P2 inv;   /* 0x60: 1/|d|, only lane 0 read -> lfs + fmr */
    P2 piv;   /* 0x68: normalising 1/sqrt(dist), pair read + lane 1 written */
    P2 pspd;  /* 0x70: {spd,0}, read twice -> psq_l + ps_mr */
    P2 phgt;  /* 0x78: {jh,0},  read twice -> psq_l + ps_mr */
    P2 inv3;  /* 0x80: 1/|v|,  only lane 0 read -> lfs + fmr */
    P2 pinv4; /* 0x88: 1/sqrt(|v|2), pair read + lane 1 written */
    __ps_t u;
    __ps_t b60;
    __ps_t b58;
    SN_PS_type s;
    SN_PS_type d;
    f32 jt;
    f32 jh;
    f32 len;
    f32 spd;
    f32 dist;
    f32 spd2;
    P2 *pv;
    V4 *seg1;

    /* WANT's `addi r31,r1,8` + `8(r31)` for the d1 slot while d2 stays
     * `8(r1)`: array-form alias for slot 1, struct field for slot 0
     * (docs/parkings/06 M5.0j-2r / recipe 6at-3 split-base form). */
    pv = &t.d2;
    GetFloat(qb, QB_HEIGHT, &t.h, 1);
    GetFloat(qb, QB_GRAVITY, &t.grav, 1);

    b58 = a->b->v58;
    b60 = a->b->v60;
    /* Declaration order v58-then-v60 is load-bearing: cc1 emits the hoisted
     * reads in REVERSE declaration order, so this gives want's
     * `a->v80 / b->v60 / b->v58 / a->v78` load sequence and its adjacent
     * `ps_sub`s. Writing the statements the other way round costs 7 words. */
    t.d2 = __builtin_ps_sub(a->v78, b58);
    t.d1 = __builtin_ps_sub(a->v80, b60);
    jt = 2.0f * sqrtf((2.0f * -t.h) / t.grav);
    jh = sqrtf(2.0f * t.grav * -t.h);

    s.ps = __builtin_ps_merge00(__builtin_ps_mul(pv[1].ps, pv[1].ps), lbl_802ABFB8);
    s.ps = __builtin_ps_madd(t.d2, t.d2, s.ps);
    s.ps = __builtin_ps_sum0(s.ps, s.ps, s.ps);
    s.ps = __builtin_ps_rsqrte(s.ps);
    s.ps = __builtin_ps_res(s.ps);
    inv.ps = s.ps;
    len = inv.f[0];

    spd = len * lbl_802AC280;
    spd = spd * fn_8012570C(QB_PED_SKATER_VERT_JUMP_SLOP_DISTANCE, 1);
    spd = spd / jt;

    d.ps = __builtin_ps_merge00(__builtin_ps_mul(pv[1].ps, pv[1].ps), lbl_802ABFB8);
    d.ps = __builtin_ps_madd(t.d2, t.d2, d.ps);
    d.ps = __builtin_ps_sum0(d.ps, d.ps, d.ps);
    dist = d.flt.hi;
    if (dist > lbl_802AC284) {
        piv.ps = __builtin_ps_rsqrte(d.ps);
        t.d2 = __builtin_ps_muls0(t.d2, piv.ps);
        piv.f[1] = lbl_802AC288;
        pv[1].ps = __builtin_ps_mul(pv[1].ps, piv.ps);
    }

    pspd.f[0] = spd;
    phgt.f[0] = jh;
    t.v2s = __builtin_ps_muls0(t.d2, pspd.ps);
    /* Taking &t.s1 is what produces want's `addi r11,r1,0x38` split base: for
     * an address-taken+indexed local ngccc keeps offset 0 fp-relative and
     * puts every nonzero offset off the base register (measured; same rule as
     * `pv[1]` -> `8(r31)` vs `t.d2` -> `8(r1)`). The {0,1} init must sit
     * BETWEEN the two ps_muls0s -- before both is 41.4%/692B, after both is
     * 40.2%/700B, between is 52.9%/696B. */
    seg1 = &t.s1;
    seg1->x.f[0] = lbl_802AC284;
    seg1->y.f[0] = lbl_802AC284;
    seg1->x.f[1] = lbl_802AC288;
    t.s1.y.f[1] = lbl_802AC288;
    t.v1s = __builtin_ps_muls0(pv[1].ps, pspd.ps);

    t.g.y.ps = __builtin_ps_muls0(t.s1.y.ps, phgt.ps);
    t.g.x.ps = __builtin_ps_muls0(t.s1.x.ps, phgt.ps);
    t.s1.y.ps = __builtin_ps_add(t.v1s, t.g.y.ps);
    t.s2.y.ps = t.s1.y.ps;
    t.s1.x.ps = __builtin_ps_add(t.v2s, t.g.x.ps);
    t.s2.x.ps = t.s1.x.ps;
    u = __builtin_ps_mul(t.s1.y.ps, t.s1.y.ps);
    u = __builtin_ps_merge00(u, lbl_802ABFB8);
    s.ps = __builtin_ps_madd(t.s1.x.ps, t.s1.x.ps, u);
    s.ps = __builtin_ps_sum0(s.ps, s.ps, s.ps);
    inv3.ps = __builtin_ps_res(__builtin_ps_rsqrte(s.ps));
    spd2 = inv3.f[0];
    if (s.flt.hi > lbl_802AC284) {
        pinv4.ps = __builtin_ps_rsqrte(s.ps);
        /* The lane-1 store goes BETWEEN the two normalising multiplies; that
         * is what yields want's `ps_mr <copy>` + `psq_st ..,136(r1)` shape
         * (before both costs a word, after both costs more). */
        t.s2.x.ps = __builtin_ps_muls0(t.s2.x.ps, pinv4.ps);
        pinv4.f[1] = lbl_802AC288;
        t.s2.y.ps = __builtin_ps_mul(t.s2.y.ps, pinv4.ps);
    }
    t.s1.x.ps = t.s2.x.ps;
    t.s1.y.ps = t.s2.y.ps;

    fn_801279A0(c->p, QB_HEADING, &t.s2.x);
    fn_8012772C(c->p, QB_JUMPSPEED, spd2);
    fn_8012772C(c->p, QB_JUMPTIME, jt);
    return 1;
}
